import { useGesture } from '@use-gesture/react';
import { PickD3Scale, TimeDomain } from '@visx/scale';
import clsx from 'clsx';
import React, { useLayoutEffect } from 'react';

import Colors from '@dynatrace/strato-design-tokens/colors';

import { svgPlotLayout } from '../../../../core/components/chart-grid/ChartGridRoot.sty.js';
import { useGridPlotSize } from '../../../../core/components/chart-grid/hooks/useGridPlotSize.js';
import { useKeyboardControls } from '../../../../core/components/overlays/hooks/useKeyboardControls.js';
import { usePanning } from '../../../../core/components/zoom/hooks/usePanning.js';
import { resizeCursor } from '../../../../core/components/zoom/ZoomCursors.sty.js';
import {
  handlePanningMovement,
  PanDirection,
} from '../../../../core/functions/zoom.js';
import {
  useCurrentDomainState,
  useSetState,
  useZoomState,
} from '../../../hooks/store/selectors.js';
import { useChartInteractions } from '../../../hooks/useChartInteractions.js';
import { useXScales } from '../../../hooks/useXScale.js';
import { leftMouseClick, middleMouseClick } from '../constants.js';
import { brushOverlay } from '../TimeseriesOverlays.sty.js';

export const TimeseriesPanMode = () => {
  const plotRef = React.useRef<SVGRectElement>(null);
  const { width, height } = useGridPlotSize();
  const { currentScale: xScale, initialScale } = useXScales();
  const initialXScaleDomain = initialScale.domain();
  const setState = useSetState();
  const { onZoomChange, pan } = useChartInteractions();
  const { activeKeyboardMode } = useZoomState();
  const currentDomain = useCurrentDomainState();
  const isChartWithZoom = Boolean(currentDomain);
  const isPanEnabled = pan?.enabled && isChartWithZoom;

  function handlePan(domain: TimeDomain) {
    setState((prev) => ({
      ...prev,
      currentDomain: domain,
    }));
  }

  function handlePanEnd([min, max]: Date[]) {
    onZoomChange?.(min, max, 'panning');
  }

  const { onDrag, onDragEnd, onWheel, onWheelEnd } = usePanning({
    initialXScale: initialScale as PickD3Scale<'time'>,
    xScale: xScale as PickD3Scale<'time'>,
    onPanning: handlePan,
    onPanningEnd: handlePanEnd,
  });

  useGesture(
    {
      onDrag,
      onDragEnd,
      onWheel,
      onWheelEnd,
    },
    {
      target: plotRef,
      eventOptions: { passive: false },
      drag: {
        filterTaps: true,
        pointer: { buttons: [leftMouseClick, middleMouseClick] },
      },
      enabled: isPanEnabled,
    },
  );

  const handleKeyboardPanning =
    (direction: PanDirection) => (largerStep: boolean, repeat: boolean) => {
      const newDomain = handlePanningMovement(
        xScale as PickD3Scale<'time', number>,
        direction,
        largerStep ? 'large' : 'small',
        initialXScaleDomain,
      );

      setState((prev) => ({ ...prev, currentDomain: newDomain }));

      if (!repeat) {
        const [start, end] = newDomain;

        onZoomChange?.(start, end, 'panning');
      }
    };

  const handleCancel = () => {
    setState((prev) => ({
      ...prev,
      zoom: {
        ...prev.zoom,
        keyboardFocusMode: prev.zoom.activeKeyboardMode,
        activeKeyboardMode: undefined,
      },
    }));
  };

  useKeyboardControls({
    ref: plotRef,
    onLeft: handleKeyboardPanning('left'),
    onRight: handleKeyboardPanning('right'),
    onCancel: handleCancel,
  });

  useLayoutEffect(() => {
    if (activeKeyboardMode === 'panning') {
      plotRef.current?.focus();
    }
  });

  return isPanEnabled ? (
    <svg className={clsx(resizeCursor, svgPlotLayout, brushOverlay)}>
      <rect
        ref={plotRef}
        x={0}
        y={0}
        width={width}
        height={height}
        fill="transparent"
        stroke={`${Colors.Border.Neutral.Default}`}
        tabIndex={activeKeyboardMode === 'panning' ? 0 : undefined}
        data-testid="panning-overlay"
      />
    </svg>
  ) : null;
};

TimeseriesPanMode['displayName'] = 'TimeseriesPanMode';
